import type { Metadata } from "next";
import Breadcrumb from "@/components/header/breadcrumb";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title: "Credit System Terms & Conditions - TravelShop Booking",
  description:
    "Learn about the TravelShop Booking Credit System Terms & Conditions. Maximize your travel experience with our professional guidelines.",
  alternates: {
    canonical: "https://travelshopbooking.com/credit-terms",
  },
};

const prose =
  "tw-text-[15px] tw-leading-[1.8] tw-text-[#5d556c] [&_p]:tw-mt-0 [&_p]:tw-mb-4 [&_h3]:tw-text-[20px] [&_h3]:tw-font-bold [&_h3]:tw-text-[#14101c] [&_h3]:tw-mt-0 [&_h3]:tw-mb-4 [&_ul]:tw-my-0 [&_ul]:tw-pl-5 [&_ul]:tw-list-disc [&_ol]:tw-pl-5 [&_li]:tw-mb-2 [&_a]:tw-text-[#854ec9] [&_a]:tw-font-semibold [&_strong]:tw-text-[#14101c]";

export default function CreditTermsPage() {
  return (
    <main className="tw-font-display tw-bg-white">
      {/* Header band */}
      <section className="tw-bg-[#faf9fc] tw-border-0 tw-border-b tw-border-solid tw-border-[#ebe7f0]">
        <div className="tw-container tw-mx-auto tw-max-w-[980px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-py-10 md:tw-py-14">
          <Breadcrumb
            items={[
              {
                pageTitle: "Credit System Terms & Conditions",
                pageUrl: "/credit-terms",
              },
            ]}
          />
          <h1 className="tw-mt-4 tw-text-[clamp(28px,4vw,44px)] tw-font-bold tw-tracking-tight tw-text-[#14101c] tw-m-0">
            Credit System Terms &amp; Conditions
          </h1>
        </div>
      </section>

      <section className="tw-py-12 md:tw-py-16">
        <div className="tw-container tw-mx-auto tw-max-w-[980px] tw-px-6 md:tw-px-8 lg:tw-px-10 tw-space-y-10 lg:tw-space-y-12">
          {/* Card 1: what is it */}
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-8 tw-items-center">
            <img
              src="/images/term1.png"
              alt="term1"
              loading="lazy"
              className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
            />
            <div className={prose}>
              <h3>What is the TravelShop Booking Credits system?</h3>
              <p>
                TravelShop Booking Credits is a virtual money application
                specific to our system that allows our members to pay a portion
                of their shopping amount for their purchases on{" "}
                <strong>travelshopbooking.com</strong>
              </p>
              <p>There are 5 kinds of Credits:</p>
              <ol type="a" className="tw-list-[lower-alpha] tw-space-y-1.5">
                <li>
                  <strong>20 € Welcome Credit;</strong> it can be earned by
                  becoming a member of the system,
                </li>
                <li>
                  <strong>5% First Booking Credit;</strong> you can gain at your
                  first booking from the system and this booking must be at
                  least 500 €,
                </li>
                <li>
                  <strong>5% Invitation Credit;</strong> you gain it after you
                  invite someone and they get an active member of our system,
                  when they book a tour that is 1000 € or more, the price&apos;s
                  5% will be your credit,
                </li>
                <li>
                  <strong>2% Guest Credit;</strong> you gain it when you become
                  a member by someone else&apos;s invitation,
                </li>
                <li>
                  <strong>1% Lucky Me Credit;</strong> you will be collecting it
                  at your every booking from the system.
                </li>
                <li>
                  <strong>5% Tag Us Credit;</strong> You will gain it when you
                  share 3 actual images or 1 actual video when you join one of
                  our tours and share it on Instagram, Facebook, Youtube, or
                  Twitter (for 6 months) the 5% month of your tour price will be
                  your Tag Us Credit and you can use it on one of our{" "}
                  <strong>optional tours</strong> as a discount.
                </li>
              </ol>
            </div>
          </div>

          {/* Rules list */}
          <div
            className={`tw-rounded-2xl tw-bg-[#faf9fc] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 md:tw-p-8 ${prose}`}
          >
            <ul className="!tw-pl-5">
              <li>
                TravelShop Booking Credits can be collectible and spent within
                certain rules as a discount for its products.
              </li>
              <li>
                It is not liquidity and can never be converted into cash. It can
                only be used as a means of payment within the rules defined in
                the system.
              </li>
              <li>
                TravelShop Booking credits can not be transferred to others.
              </li>
              <li>
                <strong>1 Credit</strong> is equal to <strong>1 €</strong> (for
                USD please check the exchange rates)
              </li>
              <li>
                No matter the way how you get a member of the system, every and
                each member have 20 € Welcome Credits.
              </li>
              <li>
                Any kinds of credits can not be used on the first bookings, you
                can use them at your second and next bookings as a discount.
              </li>
              <li>
                TravelShop Booking can arrange campaigns about gaining and
                spending Credits at certain times and keep the right to change
                the rules of the campaigns.
              </li>
              <li>
                Above the <strong>campaigns</strong> and{" "}
                <strong>conditions</strong> link you can learn more about
                current campaigns and conditions.
              </li>
              <li>
                All the Credits have to be used in the following 1 year from the
                first booking. Unused credits are automatically deleted from the
                system after 1 year.
              </li>
              <li>
                Only travelshopbooking.com members can collect and use credits.
              </li>
              <li>
                The credits assigned to your account after your first booking on
                the system. They can be used as a discount starting from your
                second and next bookings.
              </li>
              <li>
                Each product/tour listed in our online store, has its own
                credit. Credits have been shown in the price information section
                on the right side of the product detail page. Every product that
                has been ordered earns you credits as much as the quantity of
                your order. So as you shop, your credits will increases.
              </li>
              <li>
                Only tours departing from Turkey are eligible for Credit offers.
              </li>
              <li>
                From the <strong>&quot;wallet&quot;</strong> section on the
                left, you can see and follow if your credit is available or not.
              </li>
              <li>You will be earning 1% credits at your every booking.</li>
              <li>Credits are valid for one year after they are given.</li>
              <li>
                Every and each shopping/booking can use only one kind of credit
                at a time.
              </li>
              <li>
                If a traveler cancels his/her booking the credits gained from
                the canceled booking are eliminated/deleted.
              </li>
            </ul>
          </div>

          {/* Card 2: how to gain */}
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-2 tw-gap-8 tw-items-center">
            <div className={`lg:tw-order-1 ${prose}`}>
              <h3>How to gain TravelShop Booking credits?</h3>
              <ul className="!tw-pl-5">
                <li>
                  In booking payments, TravelShop Booking Credits will be
                  deducted from the payment amount when you wish to use them.
                  But you can prefer not to use them and collect more to use
                  some other time within the year.
                </li>
                <li>
                  To use the Credits as a discount from the amount to be paid,
                  you have to book/buy at least a 500 € tour, otherwise your
                  Credits will wait for the next bookings.
                </li>
                <li>
                  Every and each credit that has been gained from the bookings,
                  getting members to the system, campaigns, and invitations, can
                  only be used in the second and next bookings all along 1 year.
                  First bookings cannot use Credits in any conditions.
                </li>
                <li>
                  Credits are earned only if the referee uses a custom invite
                  link from the referrer, creates a TravelShop Booking account,
                  and has a reservation for Turkey destinations.
                </li>
              </ul>
            </div>
            <img
              src="/images/term2.webp"
              alt="term2"
              loading="lazy"
              className="lg:tw-order-2 tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
            />
          </div>

          {/* Card 3: invitation */}
          <div className="tw-grid tw-grid-cols-1 lg:tw-grid-cols-[320px_1fr] tw-gap-8 tw-items-center">
            <img
              src="/images/term3.webp"
              alt="term2"
              loading="lazy"
              className="tw-w-full tw-rounded-2xl tw-object-cover tw-shadow-xl tw-shadow-[#14101c]/10"
            />
            <div className={prose}>
              <h3>How does the invitation system work?</h3>
              <ol className="!tw-pl-5 tw-list-decimal">
                <li>Introduce your family/friend to TravelShop Booking,</li>
                <li>
                  Send them the disposable link you received from
                  TravelShop Booking.
                </li>
                <li>
                  We will notify you of your travel credit via email after your
                  friend/family registers a user account and buys a trip.
                </li>
                <li>
                  When your invitation becomes a membership and{" "}
                  <strong>does their first booking</strong> 5% Invitation Credit
                  will be defined on your account,
                </li>
                <li>
                  New member gains 2% Guest Credit at the end of this process
                  automatically.
                </li>
                <li>Book your next trip.</li>
                <li>
                  Click the &quot;Use Your Wallet&quot; section on the paying
                  stage and use your credits.
                </li>
              </ol>
            </div>
          </div>

          {/* Attention */}
          <div
            className={`tw-rounded-2xl tw-bg-[#faf8ff] tw-border tw-border-solid tw-border-[#ebe7f0] tw-p-6 md:tw-p-8 ${prose}`}
          >
            <p>
              <strong>Attention:</strong>
            </p>
            <ol className="!tw-pl-5 tw-list-decimal">
              <li>
                Invitation credits cannot be earned by married couples, parents,
                and children or those who live together and are younger than 18
                years old. No problem with the cousins, co-workers,
                second-degree relatives, and else…
              </li>
              <li>
                As mentioned on the main page &apos;
                <strong>Lowest Price Guarantee</strong>&apos; section, if you
                find a better price for the same services within 24 hours of
                booking, the difference is refunded as a credit to your account.
              </li>
            </ol>
            <p>
              TravelShop Booking holds the right to cancel travel credit if
              suspected of any abuse, gaming or misuse that is contrary to the
              principles of all kinds of Credit program.
            </p>
            <p className="!tw-mb-0">Regards.</p>
          </div>
        </div>
      </section>
    </main>
  );
}
